<?php

declare(strict_types=1);

use App\Core\Database;use App\Core\Session;use App\Services\Shipping\ShippingQuoteService;use Dotenv\Dotenv;

$root=dirname(__DIR__);require $root.'/vendor/autoload.php';Dotenv::createImmutable($root)->safeLoad();Session::start();$pdo=Database::connection();
$statement=$pdo->query("SELECT p.store_id,p.seller_id,st.name store_name,COALESCE((SELECT sa.postal_code FROM store_addresses sa WHERE sa.store_id=COALESCE(st.shipping_source_store_id,st.id) AND sa.is_shipping_origin=1 ORDER BY sa.id LIMIT 1),(SELECT w.postal_code FROM warehouses w WHERE w.seller_id=p.seller_id AND w.status='active' ORDER BY w.id LIMIT 1)) origin_postal_code,v.id variant_id,COALESCE(v.promotional_price,v.price) unit_price,COALESCE(v.weight,p.weight,0.1) shipping_weight,COALESCE(v.width,p.width,11) shipping_width,COALESCE(v.height,p.height,2) shipping_height,COALESCE(v.length,p.length,16) shipping_length FROM products p JOIN product_variants v ON v.product_id=p.id JOIN stores st ON st.id=p.store_id WHERE p.status='active' AND p.platform_paused=0 AND v.status='active' AND st.status='active' LIMIT 1");$item=$statement->fetch();if(!$item){echo "PRODUCT_SHIPPING=SKIPPED no_active_product\n";exit(0);}if(strlen(preg_replace('/\D+/','',(string)$item['origin_postal_code'])??'')!==8){echo "PRODUCT_SHIPPING=SKIPPED no_origin_postal_code\n";exit(0);}$item['quantity']=1;$group=['store_id'=>(int)$item['store_id'],'store_name'=>$item['store_name'],'origin_postal_code'=>$item['origin_postal_code'],'items'=>[$item]];$quotes=(new ShippingQuoteService())->quotes(['groups'=>[$group]],'01310100',true);$store=$quotes['stores'][(int)$item['store_id']]??[];$options=$store['options']??[];if(!$options){fwrite(STDERR,'PRODUCT_SHIPPING=FAILED '.($store['message']??$quotes['message']??'no options').PHP_EOL);exit(1);}echo 'PRODUCT_SHIPPING=QUOTED options='.count($options).' cheapest='.number_format((float)$options[0]['price'],2,'.','').' deadline='.$options[0]['min_days'].'-'.$options[0]['max_days'].PHP_EOL;
